final class SessionFwd: Session {
    private let target: Session
    private let lock = NSLock()
    private var revoked = false
    func write(_ bytes: [UInt8]) throws {
        lock.lock(); defer { lock.unlock() }
        if revoked { throw CapabilityRevoked() }
        try target.write(bytes)
    }
    func revoke() { lock.lock(); revoked = true; lock.unlock() }   // grantor only
}

