final class SessionProxy: NSProxy {
    private let target: Session
    private var revoked = false
    override func methodSignatureForSelector(_ sel: Selector) -> NSMethodSignature? {
        return (target as AnyObject).methodSignature(for: sel)
    }
    override func forwardInvocation(_ inv: NSInvocation) {
        if revoked { NSException(name: .invalidArgumentException, reason: "capability revoked").raise() }
        inv.invoke(with: target)
    }
    func revoke() { revoked = true }
}
